"""Algorithm 2: certified good-prime injection (the counterexample machine)."""

from __future__ import annotations

from fractions import Fraction
from math import isqrt
from typing import Dict, List, Optional, Tuple


def factorize(n: int, bound: int = 2_000_000) -> Dict[int, int]:
    """Trial-division factorisation of |n|; any unfactored cofactor is a single key."""
    n, f, d = abs(n), {}, 2
    while d * d <= n and d <= bound:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f


def integral_points(N: int, lo: int = -40, hi: int = 200) -> List[Tuple[int, int]]:
    """All integral points (x, y), y > 0, with lo <= x <= hi."""
    pts: List[Tuple[int, int]] = []
    for x in range(lo, hi + 1):
        t = x**3 + N
        if t > 0:
            r = isqrt(t)
            if r * r == t:
                pts.append((x, r))
    return pts


def certify_counterexample(N: int) -> Optional[Tuple[Tuple[int, int], int, int]]:
    """Search for an integral point (x, y) on E_N and a prime l with l | y, l not | 6N.

    Returns ((x, y), l, den x(2P)) if found.  By the counterexample criterion, l is a
    prime of good reduction dividing den x(2P), refuting the "only bad primes"
    conjecture for (N, P).  The certificate is verified before it is returned.
    """
    for (x, y) in integral_points(N):
        if y == 0:
            continue
        for ell in factorize(y):
            if (6 * N) % ell != 0 and ell > 1:
                x2 = (Fraction(x) ** 4 - 8 * N * x) / (4 * (Fraction(x) ** 3 + N))
                assert x2.denominator % ell == 0, "criterion failed -- impossible"
                return ((x, y), ell, x2.denominator)
    return None

"""Algorithm 3: l-adic entry and persistence predictor for denominator valuations."""

from __future__ import annotations

from fractions import Fraction
from math import isqrt
from typing import Dict, List, Tuple


def factorize(n: int, bound: int = 2_000_000) -> Dict[int, int]:
    n, f, d = abs(n), {}, 2
    while d * d <= n and d <= bound:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f


def valuation(n: int, p: int) -> int:
    v = 0
    n = abs(n)
    while n % p == 0:
        n //= p
        v += 1
    return v


def predict_next_valuations(
    N: int, P: Tuple[Fraction, Fraction]
) -> Dict[int, int]:
    """Predict v_l(den x(2P)) for every relevant prime l, using only P.

    Rules (all theorems):
      * l | den x(P), l odd  ->  v_l(den x(2P)) = v_l(den x(P));
      * l = 2 | den x(P)     ->  v_2(den x(2P)) = v_2(den x(P)) + 2;
      * l does not divide 6N nor den x(P)  ->  v_l(den x(2P)) = 2 v_l(num y(P)).
    """
    x, y = P
    if y**2 != x**3 + N:
        raise ValueError("point not on the curve")
    if y == 0:
        raise ValueError("point of order two")
    e = isqrt(x.denominator)
    pred: Dict[int, int] = {}
    for p, a in factorize(e).items():                     # already present
        pred[p] = 2 * a + (2 if p == 2 else 0)
    for p in factorize(y.numerator):                      # entering good primes
        if p not in pred and (6 * N) % p != 0:
            pred[p] = 2 * valuation(y.numerator, p)
    return pred


def verify_prediction(N: int, P: Tuple[Fraction, Fraction]) -> bool:
    """Check the prediction against the actual denominator of x(2P)."""
    x, y = P
    x2 = (x**4 - 8 * N * x) / (4 * (x**3 + N))
    e2 = isqrt(x2.denominator)
    actual = {p: 2 * a for p, a in factorize(e2).items()}
    pred = predict_next_valuations(N, P)
    return all(actual.get(p, 0) == v for p, v in pred.items())
